import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788342097000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>All configuration is by environment variable; there is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>NTFY_URL</code></td><td>yes</td><td>—</td><td>Base URL of the ntfy instance, e.g. <code>https://ntfy.example.net</code>. There is deliberately no default</td></tr><tr><td><code>NTFY_TOKEN</code></td><td>no</td><td>—</td><td>Access token (<code>tk_…</code>). Mutually exclusive with the two below</td></tr><tr><td><code>NTFY_USERNAME</code></td><td>no</td><td>—</td><td>Basic-auth user. Must be set together with <code>NTFY_PASSWORD</code></td></tr><tr><td><code>NTFY_PASSWORD</code></td><td>no</td><td>—</td><td>Basic-auth password</td></tr><tr><td><code>NTFY_TOPICS</code></td><td>no</td><td>—</td><td>Comma-separated topics this server may use. The first is the default when a tool omits one, and the list restricts every tool, read and write — grants included</td></tr><tr><td><code>NTFY_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code>, <code>1</code> or <code>yes</code>, any case, registers only the six read tools. Note the default</td></tr><tr><td><code>NTFY_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>NTFY_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>NTFY_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> <code>1</code>, <code>off</code> or a typo stop the server with exit code 1 rather than falling back to the default. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em> <code>NTFY_TOKEN</code> and <code>NTFY_PASSWORD</code> are deleted from <code>process.env</code>, so the fatal path cannot leave a credential sitting there for a crash reporter.</p><h2 id="ntfy-url-has-no-default" tabindex="-1"><code>NTFY_URL</code> has no default <a class="header-anchor" href="#ntfy-url-has-no-default" aria-label="Permalink to “NTFY_URL has no default”">​</a></h2><p><code>https://ntfy.sh</code> would be the obvious default and the worst possible one: a server that was misconfigured, or never configured, would publish to the public internet rather than failing.</p><p>A missing URL is a warning, not a fatal error — the server has to complete the MCP handshake and answer <code>tools/list</code> without it, so registries and sandbox inspectors can introspect it. Every call then returns setup instructions. A URL that does not parse, uses a scheme other than <code>http</code>/<code>https</code>, or carries credentials in the URL does stop the server; that one could send the credentials to the wrong host.</p><p>Use <code>https://</code>. Over plain <code>http</code> the credentials cross the network unencrypted, and the server warns unless the host is loopback — <code>http://127.0.0.1:8080</code> for a local instance passes without comment.</p><h2 id="credentials-are-optional-and-exclusive" tabindex="-1">Credentials are optional, and exclusive <a class="header-anchor" href="#credentials-are-optional-and-exclusive" aria-label="Permalink to “Credentials are optional, and exclusive”">​</a></h2><p>An open ntfy instance allows publishing and subscribing without credentials, so anonymous is a supported state rather than an error.</p><p>Where credentials exist there are two forms: an access token in <code>NTFY_TOKEN</code>, or <code>NTFY_USERNAME</code> together with <code>NTFY_PASSWORD</code>. Basic auth is here because <code>ntfy user add</code> produces a username and a password rather than a token.</p><div class="danger custom-block"><p class="custom-block-title">Setting both forms stops the server</p><p><code>NTFY_TOKEN</code> alongside <code>NTFY_USERNAME</code>/<code>NTFY_PASSWORD</code> is refused at startup rather than resolved by a precedence rule. Which credential is in force must never be ambiguous. Setting only one half of the basic-auth pair is refused for the same reason.</p></div><p><code>NTFY_TOKEN</code> and <code>NTFY_PASSWORD</code> are read once and then deleted from <code>process.env</code>, before any other branch runs, so neither is visible to a child process or in <code>/proc/&lt;pid&gt;/environ</code>.</p><h2 id="ntfy-topics-is-a-default-and-a-fence" tabindex="-1"><code>NTFY_TOPICS</code> is a default and a fence <a class="header-anchor" href="#ntfy-topics-is-a-default-and-a-fence" aria-label="Permalink to “NTFY_TOPICS is a default and a fence”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">NTFY_TOPICS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">alerts,deploys,backups</span></span></code></pre></div><p>The first entry is the default for any tool called without a topic; the whole list bounds every tool, read and write. One variable rather than a separate default and allowlist, because a topic name is a bearer secret on ntfy and someone who sets a default without a restriction has bought no safety while believing they have.</p><p>Unset means no default and no restriction. Every entry must be a valid ntfy topic — 1 to 64 characters of letters, digits, <code>-</code> and <code>_</code> — and a bad entry stops the server, reported by <strong>position rather than by value</strong>: a stray line in a compose file is what lands in this variable, and stderr is the host&#39;s log file.</p><h2 id="ntfy-read-only-defaults-to-false" tabindex="-1"><code>NTFY_READ_ONLY</code> defaults to <code>false</code> <a class="header-anchor" href="#ntfy-read-only-defaults-to-false" aria-label="Permalink to “NTFY_READ_ONLY defaults to false”">​</a></h2><p>Unlike <a href="https://github.com/ni-c/imap-mcp" target="_blank" rel="noreferrer">imap-mcp</a>, where the same variable defaults to <code>true</code>. ntfy exists to publish, and a read-only default would ship a notification server that cannot notify.</p><p><code>true</code>, <code>1</code> and <code>yes</code> all disable the write tools, in any case. A switch that <em>adds</em> a protection is parsed generously on purpose — an equality check against <code>true</code> left <code>NTFY_READ_ONLY=1</code> with every write tool registered and printed nothing, because nothing prints for a variable that parsed to false. <code>NTFY_INSECURE_TLS</code> is strict for the mirror-image reason: it removes a protection, so anything it does not recognise has to mean &quot;keep validating&quot;.</p><p><strong>A genuine typo still fails open</strong>, because the default is permissive: <code>NTFY_READ_ONLY=ture</code> is not one of the three and leaves the write tools enabled, where in imap-mcp it would fail closed. The destructive tools are gated behind the approval dialog and ntfy&#39;s own permissions instead, and <code>NTFY_ALLOW_TOOLS=essential</code> or a <code>NTFY_DENY_TOOLS</code> list is the recommended hardening:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">NTFY_TOPICS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">deploys</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">NTFY_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">          # or:</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">NTFY_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_messages,create_user,delete_user,manage_user_access</span></span></code></pre></div><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p><code>NTFY_ALLOW_TOOLS</code> and <code>NTFY_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated six, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>publish_message,list_messages</code></td><td>exactly those two</td></tr><tr><td><code>list_*</code></td><td><code>list_messages</code>, <code>list_users</code></td></tr><tr><td><code>essential,get_account</code></td><td>the preset plus one more</td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>NTFY_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_user</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>NTFY_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. A preset member that read-only suppresses is dropped silently, because nobody typed it. Deny entries are exempt throughout: denying an already-suppressed tool is how a defensive list is written.</p><h2 id="ntfy-insecure-tls" tabindex="-1"><code>NTFY_INSECURE_TLS</code> <a class="header-anchor" href="#ntfy-insecure-tls" aria-label="Permalink to “NTFY_INSECURE_TLS”">​</a></h2><p>Exactly <code>true</code> accepts a self-signed certificate — <code>1</code> and <code>yes</code> do not, unlike <code>NTFY_READ_ONLY</code>. The asymmetry is the point: this variable removes a protection, so a value the parser does not recognise has to leave validation on.</p><p>It is scoped to this connection rather than setting <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so certificate validation stays on for everything else in the process. Prefer a proper internal CA in the trust store.</p>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};